  width: 49%;
  height: 100%;
  cursor: pointer;
  display: block;
}

.lb-prev {
  left: 0;
  float: left;
}

.lb-next {
  right: 0;
  float: right;
}

.lb-prev,
.lb-next {
  display: block;
  width: 30px;
  height: 30px;
  position: relative;
  cursor: pointer;
}

.lb-prev::before,
.lb-next::before {
  content: '';
  position: absolute;
  border: solid #FFF;
  border-width: 0 3px 3px 0;
  display: inline-block;
  padding: 9px;
